/**
 * profileCardEnhancer.js
 * ------------------------------------------------------------
 * The Profile tab's card markup is generated by the obfuscated
 * renderSavedList() inside popup.js. Rather than risk hand-editing
 * minified code, this watches #savedList with a MutationObserver
 * and, every time a fresh set of cards is rendered, upgrades their
 * DOM in place:
 *   - strips the leading "1. " off the name and shows it as a
 *     numbered badge instead
 *   - adds a circular avatar with the customer's initials
 *   - restyles the mobile number as a small "ID" pill
 * It never touches or removes the Load/Update/Delete buttons, so
 * their existing click behaviour (wired by popup.js) is untouched.
 * ------------------------------------------------------------
 */

(function () {

  // Curated gradient pairs — matches the app's navy/gold "official
  // record" palette instead of random/clashing hues.
  const AVATAR_PALETTE = [
    ["#1c2b4a", "#3a4d78"], // navy
    ["#b9832f", "#d9a44e"], // gold
    ["#3f6b52", "#5c9373"], // forest
    ["#7a3b3b", "#a5574f"], // maroon
    ["#3b5f7a", "#5c8aa5"], // steel blue
    ["#6b4a7a", "#8f66a5"], // plum
  ];

  function initials(name) {
    const words = name.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) return "?";
    if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
    return (words[0][0] + words[1][0]).toUpperCase();
  }

  function paletteFor(index) {
    return AVATAR_PALETTE[index % AVATAR_PALETTE.length];
  }

  function enhanceCard(card, index) {
    const info = card.querySelector(":scope > div:first-child");
    if (!info || info.classList.contains("saathi-info-enhanced")) return;

    const h2 = info.querySelector("h2");
    if (!h2) return;

    // Pull "N. Name" apart — number becomes a badge, h2 keeps just the name.
    let serial = index + 1;
    const match = h2.textContent.match(/^\s*(\d+)\.\s*(.+)$/);
    let name = h2.textContent.trim();
    if (match) {
      serial = match[1];
      name = match[2].trim();
    }
    h2.textContent = name;

    // Find the mobile line: any direct child of `info` other than h2
    // whose text mentions "Mobile".
    let mobileEl = null;
    info.querySelectorAll(":scope > div").forEach(el => {
      if (/mobile/i.test(el.textContent)) mobileEl = el;
    });

    let mobileDigits = "";
    if (mobileEl) {
      const digits = mobileEl.textContent.replace(/\D/g, "");
      mobileDigits = digits;
      mobileEl.textContent = digits ? `📲 ID: ${digits}` : "ID: not added yet";
      mobileEl.classList.add("saathi-userid");
      if (!digits) mobileEl.classList.add("saathi-userid-empty");
    }

    const [c1, c2] = paletteFor(index);

    const avatarWrap = document.createElement("div");
    avatarWrap.className = "saathi-avatar-wrap";
    avatarWrap.innerHTML = `
      <div class="saathi-serial">${serial}</div>
      <div class="saathi-avatar" style="background: linear-gradient(135deg, ${c1}, ${c2});">
        ${initials(name)}
      </div>
    `;

    const meta = document.createElement("div");
    meta.className = "saathi-meta";

    // Move (not clone, not wipe) just the name + mobile line so any
    // other children of `info` — importantly the Load/Update/Delete
    // buttons, which live in this SAME div — are left exactly where
    // they are and keep working.
    meta.appendChild(h2);
    if (mobileEl) meta.appendChild(mobileEl);

    info.insertBefore(meta, info.firstChild);
    info.insertBefore(avatarWrap, meta);
    info.classList.add("saathi-info-enhanced");

    // Colour the action buttons by their actual text instead of their
    // sibling position — nth-last-child position shifted once we added
    // avatarWrap/meta as new siblings, which made the old CSS fragile.
    info.querySelectorAll(":scope > button").forEach(btn => {
      const label = btn.textContent.trim().toLowerCase();
      btn.classList.remove("saathi-btn-load", "saathi-btn-update", "saathi-btn-delete");
      if (label.includes("load")) btn.classList.add("saathi-btn-load");
      else if (label.includes("update")) btn.classList.add("saathi-btn-update");
      else if (label.includes("delete")) btn.classList.add("saathi-btn-delete");
    });
  }

  function enhanceAll() {
    const cards = document.querySelectorAll("#savedList > div");
    cards.forEach((card, idx) => enhanceCard(card, idx));
  }

  function init() {
    const list = document.getElementById("savedList");
    if (!list) return;

    enhanceAll(); // in case it's already populated

    const observer = new MutationObserver(() => enhanceAll());
    observer.observe(list, { childList: true, subtree: true });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
